-- phb-spells: Player's Handbook v3.5 spell definitions (batched).
-- Source of truth: individual spell descriptions, pp. 196-303.
-- 605 spell entries. Concise rules_text preserves the spell's operative summary; source_page remains authoritative.
-- Requires 00-catalog.sql. Safe to re-run.

INSERT OR IGNORE INTO dnd35_spells
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,school_id,subschool,casting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,saving_throw_text,save,spell_resistance,spell_resistance_text) VALUES
  ('phb-spell-animate-rope','phb-3.5','199','animate-rope','Animate Rope','You can animate a nonliving ropelike object, such as string, yarn, cord, line, rope, or even a cable.','You can animate a nonliving ropelike object, such as string, yarn, cord, line, rope, or even a cable. The maximum length assumes a rope with a 1-inch diameter.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','One ropelike object, length up to 50 ft. + 5 ft./level; see text',NULL,NULL,'1 round/level','None',NULL,'no','No'),
  ('phb-spell-antilife-shell','phb-3.5','199','antilife-shell','Antilife Shell','You bring into being a mobile, hemispherical energy field that prevents the entrance of most types of living creatures.','You bring into being a mobile, hemispherical energy field that prevents the entrance of most types of living creatures.',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 round','other','10 ft.',NULL,'10-ft.-radius emanation, centered on you',NULL,'10 min./level (D)','None',NULL,'yes','Yes'),
  ('phb-spell-antimagic-field','phb-3.5','200','antimagic-field','Antimagic Field','An invisible barrier surrounds you and moves with you. The space within this barrier is impervious to most magical effects, including…','An invisible barrier surrounds you and moves with you. The space within this barrier is impervious to most magical effects, including spells, spell-like abilities, and supernatural abilities.',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 standard action','standard','10 ft.',NULL,'10-ft.-radius emanation, centered on you',NULL,'10 min./level (D)','None',NULL,'conditional','See text'),
  ('phb-spell-antipathy','phb-3.5','200','antipathy','Antipathy','You cause an object or location to emanate magical vibrations that repel either a specific kind of intelligent creature or creatures of a…','You cause an object or location to emanate magical vibrations that repel either a specific kind of intelligent creature or creatures of a particular alignment, as defined by you.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 hour','other','Close (25 ft. + 5 ft./2 levels)','One location (up to a 10-ft. cube/level) or one object',NULL,NULL,'2 hours/level (D)','Will partial','will','yes','Yes'),
  ('phb-spell-antiplant-shell','phb-3.5','200','antiplant-shell','Antiplant Shell','The antiplant shell spell creates an invisible, mobile barrier that keeps all creatures within the shell protected from attacks by plant…','The antiplant shell spell creates an invisible, mobile barrier that keeps all creatures within the shell protected from attacks by plant creatures or animated plants.',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 standard action','standard','10 ft.',NULL,'10-ft.-radius emanation, centered on you',NULL,'10 min./level (D)','None',NULL,'yes','Yes'),
  ('phb-spell-arcane-eye','phb-3.5','200','arcane-eye','Arcane Eye','You create an invisible magical sensor that sends you visual information.','You create an invisible magical sensor that sends you visual information. You can create the arcane eye at any point you can see, but it can then travel outside your line of sight without hindrance.',0,NULL,1,'phb-spell-school-divination','Scrying','10 minutes','other','Unlimited',NULL,NULL,'Magical sensor','1 min./level (D)','None',NULL,'no','No'),
  ('phb-spell-arcane-lock','phb-3.5','200','arcane-lock','Arcane Lock','An arcane lock spell cast upon a door, chest, or portal magically locks it.','An arcane lock spell cast upon a door, chest, or portal magically locks it. You can freely pass your own arcane lock without affecting it; otherwise, a door or object secured with this spell can be opened only by breaking in or with a successful dispel magic…',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 standard action','standard','Touch','The door, chest, or portal touched, up to 30 sq. ft./level in size',NULL,NULL,'Permanent','None',NULL,'no','No'),
  ('phb-spell-arcane-mark','phb-3.5','201','arcane-mark','Arcane Mark','This spell allows you to inscribe your personal rune or mark, which can consist of no more than six characters.','This spell allows you to inscribe your personal rune or mark, which can consist of no more than six characters. The writing can be visible or invisible.',0,NULL,1,'phb-spell-school-universal',NULL,'1 standard action','standard','0 ft.',NULL,NULL,'One personal rune or mark, all of which must fit within 1 sq. ft.','Permanent','None',NULL,'no','No'),
  ('phb-spell-arcane-sight','phb-3.5','201','arcane-sight','Arcane Sight','This spell makes your eyes glow blue and allows you to see magical auras within 120 feet of you.','This spell makes your eyes glow blue and allows you to see magical auras within 120 feet of you. The effect is similar to that of a detect magic spell, but arcane sight does not require concentration and discerns aura location and power more quickly.',0,NULL,1,'phb-spell-school-divination',NULL,'1 standard action','standard','Personal','You','Cone-shaped emanation',NULL,'1 min./level (D)','None',NULL,'no','No'),
  ('phb-spell-arcane-sight-greater','phb-3.5','201','arcane-sight-greater','Arcane Sight, Greater','This spell functions like arcane sight, except that you automatically know which spells or magical effects are active upon any individual…','This spell functions like arcane sight, except that you automatically know which spells or magical effects are active upon any individual or object you see. Greater arcane sight doesn’t let you identify magic items.',0,NULL,1,'phb-spell-school-divination',NULL,'1 standard action','standard','Personal','You','Cone-shaped emanation',NULL,'1 min./level (D)','None',NULL,'no','No'),
  ('phb-spell-astral-projection','phb-3.5','201','astral-projection','Astral Projection','By freeing your spirit from your physical body, this spell allows you to project an astral body onto another plane altogether.','By freeing your spirit from your physical body, this spell allows you to project an astral body onto another plane altogether.',0,NULL,1,'phb-spell-school-necromancy',NULL,'30 minutes','other','Touch','You plus one additional willing creature touched per two caster levels',NULL,NULL,'See text','None',NULL,'yes','Yes'),
  ('phb-spell-atonement','phb-3.5','201','atonement','Atonement','This spell removes the burden of evil acts or misdeeds from the subject.','This spell removes the burden of evil acts or misdeeds from the subject. The creature seeking atonement must be truly repentant and desirous of setting right its misdeeds.',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 hour','other','Touch','Living creature touched',NULL,NULL,'Instantaneous','None',NULL,'yes','Yes'),
  ('phb-spell-augury','phb-3.5','202','augury','Augury','An augury can tell you whether a particular action will bring good or bad results for you in the immediate future.','An augury can tell you whether a particular action will bring good or bad results for you in the immediate future. For example, if a character is considering destroying a weird seal that closes a portal, an augury might determine whether that act is a good…',0,NULL,1,'phb-spell-school-divination',NULL,'1 minute','other','Personal','You',NULL,NULL,'Instantaneous','Will disbelief (if inter- acted with), then Fortitude partial; see text',NULL,'yes','Yes'),
  ('phb-spell-awaken','phb-3.5','202','awaken','Awaken','You awaken a tree or animal to humanlike sentience. To succeed, you must make a Will save (DC 10 + the animal’s current HD, or the HD the…','You awaken a tree or animal to humanlike sentience. To succeed, you must make a Will save (DC 10 + the animal’s current HD, or the HD the tree will have once awakened). The awakened animal or tree is friendly toward you.',0,NULL,1,'phb-spell-school-transmutation',NULL,'24 hours','other','Touch','Animal or tree touched',NULL,'One mount','Instantaneous','Will negates','will','yes','Yes'),
  ('phb-spell-baleful-polymorph','phb-3.5','202','baleful-polymorph','Baleful Polymorph','You change the subject into a Small or smaller animal of no more than 1 HD (such as a dog, lizard, monkey, or toad).','You change the subject into a Small or smaller animal of no more than 1 HD (such as a dog, lizard, monkey, or toad). The subject takes on all the statistics and special abilities of an average member of the new form in place of its own except as follows: o…',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature','One or more living creatures within a 10-ft.-radius burst tures with the fewest HD are affected first.',NULL,'Permanent','Fortitude negates, Will partial; see text',NULL,'yes','Yes');
